#!/bin/sh
# CTF-Logger browser wrapper - generated by ctf-logger.
# The desktop launchers of Firefox / Chrome / Chromium / Brave are pointed at this script
# (via ~/.local/share/applications overrides). While a ctf-logger session runs it sets
# SSLKEYLOGFILE, so the browser writes its TLS keys and Wireshark can decrypt the HTTPS
# traffic in the session's pcaps. Usage: browser-wrap.sh <real command> [args...]
m='{{MARKER}}'
if [ -r "$m" ]; then
    d="$(sed -n 1p "$m")"
    p="$(sed -n 2p "$m")"
    if [ -n "$p" ] && [ -d "/proc/$p" ] && [ -w "$d/browser/tls_keys.log" ]; then
        SSLKEYLOGFILE="$d/browser/tls_keys.log"
        export SSLKEYLOGFILE
    fi
fi
exec "$@"
